--
-- Name: token; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."token" AS
 SELECT (("current_setting"('request.jwt.claims'::"text", true))::"json" ->> 'user_id'::"text") AS "user_id",
    (("current_setting"('request.jwt.claims'::"text", true))::"json" ->> 'cust_id'::"text") AS "cust_id",
    (("current_setting"('request.jwt.claims'::"text", true))::"json" ->> 'entitlements'::"text") AS "entitlements",
    (("current_setting"('request.jwt.claims'::"text", true))::"json" ->> 'role_id'::"text") AS "role_id",
    (("current_setting"('request.jwt.claims'::"text", true))::"json" ->> 'proj_id'::"text") AS "proj_id",
    (("current_setting"('request.jwt.claims'::"text", true))::"json" ->> 'exp'::"text") AS "exp";


--
-- Name: asset_list; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."asset_list" AS
 SELECT "asset"."asset_id",
    "asset"."proj_id",
    "asset"."gai",
    "asset"."name",
    "asset"."loc_path",
    "asset"."func_path",
    "asset"."asset_type",
    "asset"."lat",
    "asset"."lon",
    "asset"."storey",
    "asset"."description",
    "asset"."tags",
    "asset"."ar",
    "asset"."tracker_id",
    "asset"."urldoc",
    "asset"."allowed_inactivity",
    "asset"."active",
    "asset"."archived",
    COALESCE((("token"."entitlements" = 'owner'::"text") OR ((("asset"."tags" IS NULL) OR ("array_length"("asset"."tags", 1) IS NULL)) AND ("acl_role"."access_untagged" IS TRUE)) OR ("acl_tags"."permissions" > 0)), false) AS "acl_access",
    ((
        CASE
            WHEN ("token"."entitlements" = 'owner'::"text") THEN 3
            ELSE 0
        END |
        CASE
            WHEN ((("asset"."tags" IS NULL) OR ("array_length"("asset"."tags", 1) IS NULL)) AND ("acl_role"."access_untagged" IS TRUE)) THEN 3
            ELSE 0
        END) | COALESCE("acl_tags"."permissions", 0)) AS "acl_permissions",
    "acl_role"."expert"
   FROM "public"."token",
    (("public"."asset"
     LEFT JOIN LATERAL ( SELECT "bit_or"("acl_tag_entries"."mask") AS "permissions"
           FROM "public"."acl_tag_entries"
          WHERE ((("acl_tag_entries"."role_id")::"text" = "token"."role_id") AND ("acl_tag_entries"."name" = ANY ("asset"."tags")))
          GROUP BY "acl_tag_entries"."role_id") "acl_tags" ON (true))
     LEFT JOIN LATERAL ( SELECT "acl_role_1"."access_untagged",
            "acl_role_1"."expert"
           FROM "public"."acl_role" "acl_role_1"
          WHERE (("acl_role_1"."role_id")::"text" = "token"."role_id")) "acl_role" ON (true))
  WHERE ((("token"."entitlements" = 'owner'::"text") OR ("asset"."proj_id" IN ( SELECT "project_user"."proj_id"
           FROM "public"."project_user"
          WHERE (("project_user"."user_id" = "token"."user_id") AND "project_user"."enable")))) AND ("asset"."archived" IS FALSE));


