--
-- Name: ticket; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW "api"."ticket" AS
 SELECT "t"."ticket_id",
    "t"."parent_id",
    "t"."title",
    "t"."description",
    "t"."priority",
    "t"."reason",
    "t"."state",
    "t"."contact",
    "t"."tags",
    "t"."created_by" AS "creator_id",
    "t"."created_at",
    "t"."assigned_to" AS "assignee_id",
    "t"."assigned_at",
    "u"."archived" AS "assignee_archived",
    "t"."closed_at",
    "t"."proj_id",
    "t"."asset_id",
    "t"."alarm_id",
    "t"."alarm",
    "a"."acl_access",
    "t"."start_at",
    "t"."end_at",
    "t"."time_spent",
    "t"."reference",
    ( SELECT "sum"("c"."time_spent") AS "sum"
           FROM "public"."ticket" "c"
          WHERE ("c"."parent_id" = "t"."ticket_id")) AS "time_spent_total"
   FROM (("public"."ticket" "t"
     LEFT JOIN "public"."asset_list" "a" ON (("a"."asset_id" = "t"."asset_id")))
     LEFT JOIN "public"."eliona_user" "u" ON (("u"."user_id" = "t"."assigned_to")))
  WHERE (("a"."acl_access" IS TRUE) OR (("a"."acl_access" = false) AND ("a"."expert" IS TRUE)) OR (("t"."asset_id" IS NULL) AND (EXISTS ( SELECT
           FROM "public"."acl_role"
          WHERE ((("acl_role"."role_id")::"text" = "public"."token_role"()) AND ("acl_role"."expert" IS TRUE))))) OR ("t"."assigned_to" = "public"."token_user"()) OR ("t"."created_by" = "public"."token_user"()));


