--
-- Name: upload_meta("text", bigint, "text", "text", "text", smallint, integer, bigint, "text", "text", "text"); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION "api"."upload_meta"("mimetype" "text", "size" bigint, "origin_filename" "text", "filename" "text" DEFAULT NULL::"text", "tag" "text" DEFAULT NULL::"text", "ver" smallint DEFAULT NULL::smallint, "asset_id" integer DEFAULT NULL::integer, "ticket_id" bigint DEFAULT NULL::bigint, "proj_id" "text" DEFAULT NULL::"text", "user_id" "text" DEFAULT NULL::"text", "asset_type" "text" DEFAULT NULL::"text") RETURNS "json"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    owner_id text = token_user();
    file_id text = gen_random_uuid ();
    ret json;
BEGIN
    INSERT INTO public.upload_meta (owner_id, file_id, size, origin_filename, tag, ver, mimetype, filename, asset_id, ticket_id, proj_id, asset_type, user_id)
        VALUES (owner_id, file_id, size, origin_filename, tag, ver, mimetype, filename, asset_id, ticket_id, proj_id, asset_type, user_id)
        -- on conflict on constraint upload_filename_idx do update set ts = now(), uuid = excluded.uuid
        -- HF Denkfehler, on conflict ist falsch!
    RETURNING
        row_to_json(upload_meta.*) INTO ret;
    RETURN ret;
END
$$;


--
