--

CREATE FUNCTION "import"."acl_role_but"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- set information, when a new acl_role was created and assigned
    IF OLD.role_id IS NULL AND NEW.role_id IS NOT NULL THEN
        NEW.imported_by = COALESCE(token_user(),'1');
        NEW.imported_at = now();
    END IF;

    NEW.modified_by  = COALESCE(token_user(),'1');
    NEW.modified_at  = now();
    NEW.modified_cnt = NEW.modified_cnt + 1;

    RETURN NEW;
END;
$$;


