--
-- Name: acl_check_access("text", integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."acl_check_access"("path" "text", "mask" integer DEFAULT 1, "role_id" integer DEFAULT NULL::integer) RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $_$
    SELECT
        TRUE
    FROM
        token
    WHERE
        entitlements = 'owner' -- access allowed to everything
        OR
        EXISTS (
            SELECT
            FROM
                public.acl_entries
                JOIN public.acl_resource USING (resource_id)
            WHERE
                role_id = coalesce($3,token.role_id::integer)
                AND path = $1
                AND mask & $2 = $2
        );
$_$;


--
-- Name: acl_check_tag_access("text"[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."acl_check_tag_access"("tags" "text"[], "mask" integer DEFAULT 1) RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $_$
    SELECT
        count(*) > 0 -- returns the real true/false
    FROM
        token
    WHERE
        entitlements = 'owner' -- access to every tag allowed
        OR
        EXISTS (
            SELECT
            FROM
                (
                    SELECT
                        role_id,
                        access_untagged
                    FROM
                        public.acl_role
                    WHERE
                        role_id = token.role_id::integer
                ) acl_role
                LEFT JOIN public.acl_tag_entries USING (role_id)
            WHERE
                (
                    -- write access to the untagged assets
                    (tags IS NULL OR array_length(tags,1) IS NULL)
                    AND
                    acl_role.access_untagged IS TRUE
                )
                OR
                (
                    name = ANY(tags)
                    AND role_id = token.role_id::integer
                    AND $2 = mask & $2
                )
        )
$_$;


