--
-- Name: alarm_id("public"."digital_twin_data"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."alarm_id"("public"."digital_twin_data") RETURNS integer
    LANGUAGE "sql" IMMUTABLE STRICT
    AS $_$
    SELECT DISTINCT ON (a.asset_id)
        alarm_id
    FROM
        public.alarm a
        JOIN public.digital_twin_content c USING (asset_id)
    WHERE (
        -- $1.show_alarm is true and
        a.subtype = $1.subtype
        AND (a.attribute = $1.attribute
            OR $1.attribute IS NULL)
    )
    ORDER BY
        asset_id,
        prio ASC
$_$;


--
-- Name: asset_delete_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."asset_delete_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF token_user () IS NOT NULL THEN -- any "API" role only marks them deleted

        -- SET ROLE "admin"; -- AL: temporary, to bypass SELECT policy (needed by UPDATE)

        -- add some random bytes and clean up device primary key
        UPDATE
            public.asset
        SET
            gai         = gai || '-' || encode(gen_random_bytes(8), 'hex'),
            device_pkey = NULL,
            deleted_by  = coalesce(token_user(),'1'),
            deleted_at  = now() -- that affects SELECT policy
        WHERE
            asset_id = OLD.asset_id;

        -- cleanup of the associated external IDs 
        DELETE FROM public.asset_pkey
        WHERE asset_id = OLD.asset_id;

        -- cleanup the alarm config
        DELETE FROM public.alarm_cfg
        WHERE asset_id = OLD.asset_id;

        RETURN NULL; -- return null, so that the record is not removed from database
    ELSE
        RETURN old;
    END IF;
END;
$$;


