--
-- Name: calendar_t_contains("public"."calendar_t", timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calendar_t_contains"("cal" "public"."calendar_t", "ts" timestamp with time zone) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    AS $$ 
    SELECT ( cal.except IS NULL OR NOT ts <@ ANY(cal.except) )
    AND ( cal.period IS NULL OR NOT ts <@ ANY(cal.period) )
    AND (
        ts <@ ANY(cal.valid) 
        OR ( SELECT ts::time <@ ANY ( 
        CASE date_part('dow',ts)::int
        WHEN 0 then cal.sun
        WHEN 1 then cal.mon
        WHEN 2 then cal.tue
        WHEN 3 then cal.wed
        WHEN 4 then cal.thu
        WHEN 5 then cal.fri
        WHEN 6 then cal.sat
        ELSE array[]::timerange[] END ) 
    ) ) ; 
$$;


