--
-- Name: eliona_user_but(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."eliona_user_but"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.modified_by = token_user();
    NEW.modified_at = now();

    IF TG_OP = 'INSERT' OR OLD.tags <> NEW.tags OR (OLD.tags IS NULL AND NEW.tags IS NOT NULL) THEN
        -- remove tags, if not valid and sort the result by category
        NEW.tags = tags_sort(NEW.tags);
    END IF;

    RETURN NEW;
END;
$$;


