    "raster" "public"."timestampraster",
    "delay" interval,
    "cnt" bigint DEFAULT 0 NOT NULL,
    "next_at" timestamp with time zone,
    "last_at" timestamp with time zone,
    "duration" interval,
    "cmd" "text" NOT NULL,
    "language" "text" DEFAULT 'plpgsql'::"text" NOT NULL,
    "body" "text",
    "is_func" boolean GENERATED ALWAYS AS (("cmd" ~ '^[A-Za-z0-9_]+$'::"text")) STORED NOT NULL,
    "arg" "text"[],
    "hidden" boolean DEFAULT false NOT NULL,
    "custom" boolean DEFAULT true NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "text" DEFAULT COALESCE("public"."token_user"(), '1'::"text"),
