    "xcp" bigint DEFAULT 0 NOT NULL,
    "xcp_message" "text",
    CONSTRAINT "crontab_language_check" CHECK (("language" = ANY (ARRAY['plpgsql'::"text", 'plpython3u'::"text"])))
);


--
-- Name: crontab_runnable; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."crontab_runnable" AS
 SELECT "crontab_id",
    "proj_id",
    "description",
    "enable",
    "singleton",
    "when",
    "raster",
    "delay",
    "cnt",
    "xcp",
    "next_at",
    "last_at",
    "duration",
    "cmd",
    "is_func",
    "arg",
    "custom"
   FROM "cron"."crontab"
  WHERE (("enable" IS TRUE) AND (("next_at" IS NULL) OR ("next_at" <= "now"())) AND (("when" IS NULL) OR ("when" OPERATOR("public".@>) "next_at")))
  ORDER BY "raster" NULLS FIRST, "next_at" NULLS FIRST;


--
-- Name: exec("public"."crontab_runnable"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."exec"("tab" "public"."crontab_runnable", OUT "id" integer, OUT "rc" bigint) RETURNS "record"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    cmd text;
BEGIN
    IF tab.is_func THEN
        EXECUTE format('select %I('
                || coalesce( LEFT (repeat('%L::unknown,', array_length(tab.arg, 1)), -1), '')
                || ')', tab.cmd, tab.arg[1], tab.arg[2], tab.arg[3], tab.arg[4], tab.arg[5]);
    ELSE
        EXECUTE tab.cmd USING tab.arg[1], tab.arg[2], tab.arg[3], tab.arg[4], tab.arg[5];
    END IF;

    RESET ROLE;

    id := tab.crontab_id;
    get diagnostics rc := ROW_COUNT;

    RETURN;
END;
$$;


--
-- Name: heap_counter(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."heap_counter"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Das ist ein reiner update-Trigger.
    -- Das allererste Insert würde, selbst wenn es eine Rasterung hätte, würde hier nicht ankommen.
    -- Insert ... on conflict .. do update schon.
    -- Leider würde dabei ein on insert or update - Trigger zweimal aufgerufen!
    -- Ein After-Trigger hat dieses Problem nicht, der wird nur zweimal markiert und hinterher einmal aufgerufen.
    NEW.update_cnt = NEW.update_cnt + 1;
    NEW.pid        = pg_backend_pid();
    IF (current_query() !~ 'source') THEN
        NEW.source = NULL; -- TODO: reset "source" spec, if not in the update
    END IF;

    RETURN NEW;
END
$$;


