--
-- Name: property_adt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."property_adt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    a text;
    t text;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.enable IS TRUE THEN
            RETURN NULL;
        ELSE
            a = NEW.attribute;
            t = NEW.asset_type;
        END IF;
    ELSE
        a = OLD.attribute;
        t = OLD.asset_type;
    END IF;

    UPDATE
        public.heap
    SET
        data = data - a
    FROM
        public.asset
    WHERE
        asset_type = t
        AND heap.asset_id = asset.asset_id;

    RETURN NULL;
END;
$$;


--
-- Name: setup_asset_heap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."setup_asset_heap"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- set default validity
    UPDATE public.asset
    SET
        active = NULLIF(at.allowed_inactivity IS NOT NULL, FALSE)
    FROM
        asset_type at
    WHERE
        asset.asset_id = NEW.asset_id
        AND at.asset_type = NEW.asset_type;

    INSERT INTO public.heap(asset_id, subtype, data)
    SELECT DISTINCT ON (subtype)
        NEW.asset_id,
        subtype,
        '{}'::jsonb
    FROM
        public.attribute_schema
    WHERE
        asset_type = NEW.asset_type
        AND subtype IN ('input', 'status', 'info')
        AND enable = TRUE;

    -- default properties
    INSERT INTO public.heap (asset_id, subtype, data)
    SELECT
        NEW.asset_id,
        subtype,
        json_object_agg(attribute, "default" -> 'value')
    FROM
        public.attribute_schema
    WHERE
        asset_type = NEW.asset_type
        AND subtype = 'property'
        AND category IS NOT NULL
        AND enable = TRUE
    GROUP BY
        subtype;

    RETURN NEW;
END;
$$;


