--
-- Name: trend_agg(integer, "text", "text", interval, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trend_agg"("asset_id" integer, "subtype" "text", "attribute" "text", "raster" interval, "start" timestamp with time zone, "end" timestamp with time zone DEFAULT "now"()) RETURNS SETOF "public"."trend_agg"
    LANGUAGE "sql" STABLE
    AS $_$
    SELECT
        asset_id,
        subtype,
        attribute,
        time_bucket($4, ts, current_setting('timezone',true)) AS ts,
        count(value) AS cnt,
        avg(value),
        sum(value),
        first(value,ts),
        min(value),
        max(value),
        last(value,ts),
        array_agg(DISTINCT change_id) FILTER(WHERE change_id IS NOT NULL),
        array_agg(DISTINCT import_id) FILTER(WHERE import_id IS NOT NULL)
    FROM
        public.trend
    WHERE
        asset_id = $1
        AND subtype = $2
        AND attribute = $3
        AND ts BETWEEN $5 AND $6
    GROUP BY
        1, 2, 3, 4
    ORDER BY
        ts ASC;
$_$;


--
-- Name: trend_agg_cusum(integer, "text", "text", interval, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trend_agg_cusum"("asset_id" integer, "subtype" "text", "attribute" "text", "raster" interval, "start" timestamp with time zone, "end" timestamp with time zone DEFAULT "now"()) RETURNS SETOF "public"."trend_agg"
    LANGUAGE "sql" STABLE
    AS $_$
    WITH bucketed AS (
        SELECT
            asset_id,
            subtype,
            attribute,
            time_bucket($4, ts, current_setting('timezone',true)) AS ts,
            count(value) AS cnt,
            min(value),
            max(value),
            last(value,ts),
            array_agg(DISTINCT change_id) FILTER(WHERE change_id IS NOT NULL) AS change_ids,
            array_agg(DISTINCT import_id) FILTER(WHERE import_id IS NOT NULL) AS import_ids
        FROM
            public.trend
        WHERE
            asset_id = $1
            AND subtype = $2
            AND attribute = $3
            AND ts BETWEEN $5 - $4 AND $6
        GROUP BY
            1, 2, 3, 4
    )
    SELECT
        asset_id,
        subtype,
        attribute,
        ts,
        cnt,
        NULL::float8,
        last - lag(last) OVER (ordered), -- sum
        lag(last) OVER (ordered), -- first
        min,
        max,
        last,
        change_ids,
        import_ids
    FROM
        bucketed
    WINDOW ordered AS (PARTITION BY asset_id, subtype, attribute ORDER BY ts)
    ORDER BY
        ts ASC;
$_$;


