    "alarm_history"."ts",
    "alarm_history"."gone_ts",
    "alarm_history"."ack_ts",
    "alarm_history"."multi",
    "alarm_history"."message",
    ("jsonb_build_object"('config', "alarm_cfg".*) || "jsonb_build_object"('asset', "asset".*)) AS "data",
    "alarm_cfg"."tags",
    "alarm_history"."ack_text",
    "alarm_history"."ack_user_id",
    "asset"."proj_id",
    "asset"."gai",
    "asset"."name",
    "asset"."asset_type",
    "alarm_cfg"."intervention"
   FROM (("public"."alarm_history"
     JOIN "public"."asset_list" "asset" USING ("asset_id"))
     JOIN "public"."alarm_cfg" USING ("alarm_id"))
  WHERE "asset"."acl_access"
  ORDER BY 2, 5;


