    "eu"."language",
    "eu"."locale",
    "eu"."timezone",
    "r"."role",
    "eu"."role_id",
    "eu"."tags",
    "eu"."validity",
    "eu"."email",
    NULL::"text" AS "password",
    "eu"."otp_enabled",
    "eu"."schema",
    "eu"."phone",
    "eu"."mobile",
    "eu"."pager",
    "eu"."mail2service",
    "eu"."slack",
    "eu"."google_chat",
