   FROM ("public"."eliona_user" "eu"
     JOIN "public"."acl_role" "r" USING ("role_id"))
  WHERE (("public"."acl_check_access"('gui.eliona.users'::"text", 1, "public"."system_role"()) OR ("eu"."user_id" = "public"."token_user"())) AND ("eu"."hidden" IS FALSE));


