--
-- Name: dashboard; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW "api"."dashboard" AS
 SELECT "d"."dashboard_id",
    "d"."user_id",
    "d"."proj_id",
    "d"."name",
    "d"."dashboard_id" AS "seq",
    "d"."public",
    "d"."asset_id"
   FROM ("public"."dashboard" "d"
     LEFT JOIN "public"."asset_list" "a" ON (("a"."asset_id" = "d"."asset_id")))
  WHERE (("a"."asset_id" IS NULL) OR ("a"."acl_access" IS TRUE) OR (("a"."acl_access" IS FALSE) AND ("a"."expert" IS TRUE)))
  ORDER BY ("d"."proj_id")::integer;


