--
-- Name: eliona_config; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."eliona_config" (
    "cust_id" "text",
    "owner_id" "text",
    "displayname" "text",
    "domain_name" "text",
    "retention_time" integer DEFAULT 24,
    "cold_storage_time" integer,
    "logfile_lifespan" integer DEFAULT 1,
    "audit_log_limitation" boolean DEFAULT false NOT NULL,
    "trend_mode" "text" DEFAULT 'batch'::"text" NOT NULL,
    "batch_period" integer DEFAULT 100,
    "version" "text",
    "latest_version" "text",
    "pk" "text",
    "secret" "text" GENERATED ALWAYS AS ("encode"("public"."digest"((("cust_id" || '.'::"text") || "displayname"), 'sha256'::"text"), 'hex'::"text")) STORED,
    "iv_attribute" numeric DEFAULT 1,
    "iv_user" numeric DEFAULT 10,
    "iv_connectivity" numeric DEFAULT 100,
    "modified_by" "text" DEFAULT (("current_setting"('request.jwt.claims'::"text", true))::"json" ->> 'user_id'::"text"),
    "modified_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "eliona_config_batch_period_check" CHECK ((("batch_period" IS NULL) OR (("batch_period" >= 10) AND ("batch_period" <= 1000)))),
    CONSTRAINT "eliona_config_cold_storage_time_check" CHECK (("cold_storage_time" = ANY (ARRAY[NULL::integer, 1, 3, 6, 12, 24, 36, 48, 60]))),
    CONSTRAINT "eliona_config_logfile_lifespan_check" CHECK ((("logfile_lifespan" IS NULL) OR (("logfile_lifespan" >= 1) AND ("logfile_lifespan" <= 12)))),
    CONSTRAINT "eliona_config_retention_time_check" CHECK (("retention_time" = ANY (ARRAY[NULL::integer, 1, 3, 6, 12, 24, 36, 48, 60]))),
    CONSTRAINT "eliona_config_trend_mode_check" CHECK (("trend_mode" = ANY (ARRAY['plain'::"text", 'batch'::"text", 'smart_batch'::"text"])))
);


--
-- Name: eliona_config; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW "api"."eliona_config" AS
 SELECT "eliona_config"."cust_id",
    "eliona_config"."owner_id",
    (("eliona_user"."firstname" || ' '::"text") || "eliona_user"."lastname") AS "owner_name",
    "eliona_config"."displayname",
    "eliona_config"."domain_name",
    "eliona_config"."retention_time",
    "eliona_config"."cold_storage_time",
    "eliona_config"."logfile_lifespan",
    "eliona_config"."audit_log_limitation",
    "eliona_config"."trend_mode",
    "eliona_config"."batch_period",
    "eliona_config"."version",
    "eliona_config"."latest_version",
    "eliona_config"."pk",
    "current_setting"('TIMEZONE'::"text") AS "timezone"
   FROM ("public"."eliona_config"
     LEFT JOIN "public"."eliona_user" ON (("eliona_config"."owner_id" = "eliona_user"."user_id")));


