    "ts" timestamp with time zone NOT NULL,
    "asset_id" integer NOT NULL,
    "subtype" "text" NOT NULL,
    "attribute" "text" NOT NULL,
    "change" "json",
    "modified_by" "text" DEFAULT "public"."token_user"(),
