);

ALTER TABLE ONLY "public"."trend_changelog" REPLICA IDENTITY FULL;


--
-- Name: upload_meta; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."upload_meta" (
    "file_id" "text" NOT NULL,
    "mimetype" "text" NOT NULL,
    "tag" "text",
    "filename" "text" NOT NULL,
    "ver" smallint,
    "origin_filename" "text",
    "data" "text",
    "size" bigint NOT NULL,
    "ts" timestamp with time zone DEFAULT "now"() NOT NULL,
    "owner_id" "text",
    "asset_id" integer,
    "ticket_id" bigint,
    "proj_id" "text",
    "user_id" "text",
    "asset_type" "text",
    CONSTRAINT "upload_meta_check" CHECK ((1 = "num_nonnulls"("asset_id", "ticket_id", "proj_id", "user_id", "asset_type"))),
    CONSTRAINT "upload_meta_mimetype_check" CHECK (("mimetype" !~* 'text/(html|xhtml|css|javascript)'::"text"))
);


--
-- Name: upload_meta; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW "api"."upload_meta" AS
 SELECT "file_id",
    "mimetype",
    "tag",
    "filename",
    "ver",
    "origin_filename",
    "data",
    "size",
    "ts",
    "owner_id",
    "asset_id",
    "ticket_id",
    "proj_id",
    "user_id",
    "asset_type"
   FROM "public"."upload_meta";


