--
-- Name: patches; Type: TABLE; Schema: versioning; Owner: -
--

CREATE TABLE "versioning"."patches" (
    "app_name" "text" NOT NULL,
    "patch_name" "text" NOT NULL,
    "applied_tsz" timestamp with time zone DEFAULT "now"() NOT NULL,
    "applied_by" "text" NOT NULL,
    "requires" "text"[],
    "conflicts" "text"[]
);


--
-- Name: latest_version; Type: VIEW; Schema: versioning; Owner: -
--

CREATE VIEW "versioning"."latest_version" AS
 SELECT DISTINCT ON ("app_name") "app_name",
    ((((('v'::"text" || ("substr"("patch_name", 1, 2))::integer) || '.'::"text") || ("substr"("patch_name", 3, 2))::integer) || '.'::"text") || ("substr"("patch_name", 5, 2))::integer) AS "version",
    "applied_tsz" AS "applied"
   FROM "versioning"."patches"
  ORDER BY "app_name", ("patch_name")::integer DESC;


--
-- Name: version; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW "api"."version" AS
 SELECT "version",
    "applied"
   FROM "versioning"."latest_version"
  WHERE ("app_name" = 'public'::"text");


