CREATE RULE "delete_alarm_cfg" AS
    ON DELETE TO "api"."alarm_cfg" DO INSTEAD  DELETE FROM "public"."alarm_cfg"
  WHERE ("alarm_cfg"."alarm_id" = "old"."alarm_id")
  RETURNING "old"."alarm_id",
    "old"."ruleengine_id",
    "old"."asset_id",
    "old"."subtype",
    "old"."attribute",
    "old"."enable",
    "old"."check_type",
    "old"."prio",
    "old"."ack_p",
    "old"."auto_ticket",
    "old"."equal",
    "old"."low",
    "old"."high",
    "old"."message",
    "old"."tags",
    "old"."params",
    "old"."urldoc",
    "old"."notify_on",
    "old"."dont_mask",
    "old"."gai",
    "old"."name",
    "old"."proj_id",
    "old"."asset_type",
    "old"."acl_access",
    "old"."intervention";


