    "s"."trend_mode",
    "s"."unit",
    "s"."formula",
    "s"."scale",
    "s"."zero",
    "s"."precision",
    "s"."min",
    "s"."max",
    "s"."step",
    "s"."map",
    "s"."agg_mode",
    "s"."viewer",
    "s"."ar",
    "s"."seq",
    "s"."virtual",
    "s"."default",
    "s"."source_path";


