--
-- Name: alarm_cfg insert_alarm_cfg; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "insert_alarm_cfg" AS
    ON INSERT TO "api"."alarm_cfg" DO INSTEAD  INSERT INTO "public"."alarm_cfg" ("asset_id", "subtype", "attribute", "check_type", "prio", "ack_p", "equal", "low", "high", "message", "tags", "params", "urldoc", "notify_on", "intervention")
  VALUES ("new"."asset_id", "new"."subtype", "new"."attribute", "new"."check_type", "new"."prio", COALESCE("new"."ack_p", false), "new"."equal", "new"."low", "new"."high", "new"."message", "new"."tags", "new"."params", "new"."urldoc", COALESCE("new"."notify_on", 'R'::"bpchar"), "new"."intervention")
  RETURNING "alarm_cfg"."alarm_id",
    "alarm_cfg"."ruleengine_id",
    "alarm_cfg"."asset_id",
    "alarm_cfg"."subtype",
    "alarm_cfg"."attribute",
    "alarm_cfg"."enable",
    "alarm_cfg"."check_type",
    "alarm_cfg"."prio",
    "alarm_cfg"."ack_p",
    "alarm_cfg"."auto_ticket",
    "alarm_cfg"."equal",
    "alarm_cfg"."low",
    "alarm_cfg"."high",
    "alarm_cfg"."message",
    "alarm_cfg"."tags",
    "alarm_cfg"."params",
    "alarm_cfg"."urldoc",
    "alarm_cfg"."notify_on",
    false AS "dont_mask",
    ( SELECT "asset"."gai"
           FROM "public"."asset"
          WHERE ("asset"."asset_id" = "alarm_cfg"."asset_id")) AS "gai",
    ( SELECT "asset"."name"
           FROM "public"."asset"
          WHERE ("asset"."asset_id" = "alarm_cfg"."asset_id")) AS "name",
    ( SELECT "asset"."proj_id"
           FROM "public"."asset"
          WHERE ("asset"."asset_id" = "alarm_cfg"."asset_id")) AS "proj_id",
    ( SELECT "asset"."asset_type"
           FROM "public"."asset"
          WHERE ("asset"."asset_id" = "alarm_cfg"."asset_id")) AS "asset_type",
    "api"."acl_access"("alarm_cfg"."asset_id") AS "acl_access",
    "alarm_cfg"."intervention";


--
-- Name: dashboard insert_dashboard; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "insert_dashboard" AS
    ON INSERT TO "api"."dashboard" DO INSTEAD  INSERT INTO "public"."dashboard" ("name", "public", "asset_id")
  VALUES ("new"."name", COALESCE("new"."public", false), "new"."asset_id")
  RETURNING "dashboard"."dashboard_id",
    "dashboard"."user_id",
    "dashboard"."proj_id",
    "dashboard"."name",
    "dashboard"."dashboard_id" AS "seq",
    "dashboard"."public",
    "dashboard"."asset_id";


--
-- Name: eliona_node insert_eliona_node; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "insert_eliona_node" AS
    ON INSERT TO "api"."eliona_node" DO INSTEAD  INSERT INTO "public"."eliona_node" ("asset_id", "vendor", "model", "description", "enable")
  VALUES ("new"."asset_id", "new"."vendor", "new"."model", "new"."description",
        CASE
            WHEN ("new"."enable" IS NULL) THEN true
            ELSE "new"."enable"
        END)
  RETURNING "eliona_node"."node_id",
    "eliona_node"."ident",
    "eliona_node"."asset_id",
    "eliona_node"."vendor",
    "eliona_node"."model",
    "eliona_node"."description",
    "eliona_node"."enable";


--
-- Name: eliona_user insert_eliona_user; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "insert_eliona_user" AS
    ON INSERT TO "api"."eliona_user" DO INSTEAD  INSERT INTO "public"."eliona_user" ("firstname", "lastname", "language", "locale", "timezone", "role_id", "tags", "validity", "email", "password", "otp_enabled", "schema", "phone", "mobile", "pager", "mail2service", "slack", "google_chat")
  VALUES ("new"."firstname", "new"."lastname", "new"."language", "new"."locale", COALESCE("new"."timezone", "current_setting"('TIMEZONE'::"text")),
        CASE
            WHEN ("new"."role_id" = 1) THEN 2
            ELSE COALESCE("new"."role_id", 2)
        END, "new"."tags", COALESCE("new"."validity", '10:00:00'::interval), "new"."email",
        CASE
            WHEN ("new"."password" IS NULL) THEN NULL::"text"
            ELSE
            CASE
                WHEN ("length"("new"."password") <> 60) THEN "public"."crypt"("new"."password", "public"."gen_salt"('bf'::"text"))
                ELSE "new"."password"
            END
        END, COALESCE("new"."otp_enabled", false), COALESCE("new"."schema", 'api'::"text"), "new"."phone", "new"."mobile", "new"."pager", "new"."mail2service", "new"."slack", "new"."google_chat")
  RETURNING "eliona_user"."user_id",
    "eliona_user"."firstname",
    "eliona_user"."lastname",
    "eliona_user"."language",
    "eliona_user"."locale",
    "eliona_user"."timezone",
    ( SELECT "r"."role"
           FROM "public"."acl_role" "r"
          WHERE ("r"."role_id" = "eliona_user"."role_id")) AS "role",
    "eliona_user"."role_id",
    "eliona_user"."tags",
    "eliona_user"."validity",
    "eliona_user"."email",
    NULL::"text" AS "password",
    "eliona_user"."otp_enabled",
    "eliona_user"."schema",
    "eliona_user"."phone",
    "eliona_user"."mobile",
    "eliona_user"."pager",
    "eliona_user"."mail2service",
    "eliona_user"."slack",
    "eliona_user"."google_chat",
    "eliona_user"."created_at",
    "eliona_user"."modified_at",
    "eliona_user"."last_login",
    "eliona_user"."archived";


--
-- Name: alarm_cfg update_alarm_cfg; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "update_alarm_cfg" AS
    ON UPDATE TO "api"."alarm_cfg" DO INSTEAD  UPDATE "public"."alarm_cfg" SET "asset_id" = "new"."asset_id", "subtype" = "new"."subtype", "attribute" = "new"."attribute", "enable" = "new"."enable", "check_type" = "new"."check_type", "prio" = "new"."prio", "ack_p" = "new"."ack_p", "equal" = "new"."equal", "low" = "new"."low", "high" = "new"."high", "message" = "new"."message", "tags" = "new"."tags", "params" = "new"."params", "urldoc" = "new"."urldoc", "notify_on" = "new"."notify_on", "intervention" = "new"."intervention"
   FROM "public"."asset"
  WHERE (("alarm_cfg"."alarm_id" = "new"."alarm_id") AND ("asset"."asset_id" = "new"."asset_id"))
  RETURNING "alarm_cfg"."alarm_id",
    "alarm_cfg"."ruleengine_id",
    "alarm_cfg"."asset_id",
    "alarm_cfg"."subtype",
    "alarm_cfg"."attribute",
    "alarm_cfg"."enable",
    "alarm_cfg"."check_type",
    "alarm_cfg"."prio",
    "alarm_cfg"."ack_p",
    "alarm_cfg"."auto_ticket",
    "alarm_cfg"."equal",
    "alarm_cfg"."low",
    "alarm_cfg"."high",
    "alarm_cfg"."message",
    "alarm_cfg"."tags",
    "alarm_cfg"."params",
    "alarm_cfg"."urldoc",
    "alarm_cfg"."notify_on",
    false AS "dont_mask",
    "asset"."gai",
    "asset"."name",
    "asset"."proj_id",
    "asset"."asset_type",
    "api"."acl_access"("alarm_cfg"."asset_id") AS "acl_access",
    "alarm_cfg"."intervention";


--
-- Name: eliona_node update_eliona_node; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "update_eliona_node" AS
    ON UPDATE TO "api"."eliona_node" DO INSTEAD  UPDATE "public"."eliona_node" SET "asset_id" = "new"."asset_id", "vendor" = "new"."vendor", "model" = "new"."model", "description" = "new"."description", "enable" =
        CASE
            WHEN ("new"."enable" IS NULL) THEN "old"."enable"
            ELSE "new"."enable"
        END
  WHERE ("eliona_node"."node_id" = "old"."node_id")
  RETURNING "eliona_node"."node_id",
    "eliona_node"."ident",
    "eliona_node"."asset_id",
    "eliona_node"."vendor",
    "eliona_node"."model",
    "eliona_node"."description",
    "eliona_node"."enable";


--
-- Name: eliona_user update_eliona_user; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "update_eliona_user" AS
    ON UPDATE TO "api"."eliona_user" DO INSTEAD  UPDATE "public"."eliona_user" "eu" SET "firstname" = "new"."firstname", "lastname" = "new"."lastname", "language" = "new"."language", "locale" = "new"."locale", "timezone" = "new"."timezone", "role_id" =
        CASE
            WHEN ("new"."role_id" = 1) THEN "old"."role_id"
            ELSE "new"."role_id"
        END, "tags" = "new"."tags", "validity" = "new"."validity", "email" = "new"."email", "password" =
        CASE
            WHEN ("new"."password" IS NULL) THEN ( SELECT "eliona_user"."password"
               FROM "public"."eliona_user"
              WHERE ("eliona_user"."user_id" = "new"."user_id"))
            ELSE
            CASE
                WHEN ("length"("new"."password") <> 60) THEN "public"."crypt"("new"."password", "public"."gen_salt"('bf'::"text"))
                ELSE "new"."password"
            END
        END, "otp_enabled" = "new"."otp_enabled", "schema" = "new"."schema", "phone" = "new"."phone", "mobile" = "new"."mobile", "pager" = "new"."pager", "mail2service" = "new"."mail2service", "slack" = "new"."slack", "google_chat" = "new"."google_chat", "archived" =
        CASE
            WHEN (("new"."archived" IS NULL) OR ("new"."archived" IS TRUE)) THEN "old"."archived"
            ELSE "new"."archived"
        END
  WHERE ("eu"."user_id" = "new"."user_id")
  RETURNING "eu"."user_id",
    "eu"."firstname",
    "eu"."lastname",
    "eu"."language",
    "eu"."locale",
    "eu"."timezone",
    ( SELECT "acl_role"."role"
           FROM "public"."acl_role"
          WHERE ("acl_role"."role_id" = "eu"."role_id")) AS "role",
    "eu"."role_id",
    "eu"."tags",
    "eu"."validity",
    "eu"."email",
    NULL::"text" AS "password",
    "eu"."otp_enabled",
    "eu"."schema",
    "eu"."phone",
    "eu"."mobile",
    "eu"."pager",
    "eu"."mail2service",
    "eu"."slack",
    "eu"."google_chat",
    "eu"."created_at",
    "eu"."modified_at",
    "eu"."last_login",
    "eu"."archived";


--
-- Name: heap update_heap; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "update_heap" AS
    ON UPDATE TO "api"."heap" DO INSTEAD  UPDATE "public"."heap" SET "his" = "new"."his"
   FROM "public"."asset"
  WHERE (("heap"."asset_id" = "old"."asset_id") AND ("heap"."subtype" = "old"."subtype"))
  RETURNING "heap"."asset_id",
    "heap"."subtype",
    "heap"."his",
    "heap"."ts",
    "heap"."data",
    "heap"."update_cnt",
    "asset"."asset_type";


--
-- Name: ticket update_ticket; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "update_ticket" AS
    ON UPDATE TO "api"."ticket" DO INSTEAD  UPDATE "public"."ticket" SET "title" = "new"."title", "description" = "new"."description", "priority" = "new"."priority", "reason" = "new"."reason", "tags" = "new"."tags", "asset_id" = "new"."asset_id", "alarm_id" = "new"."alarm_id", "alarm" = ( SELECT "row_to_json"("a".*) AS "row_to_json"
           FROM "public"."alarm" "a"
          WHERE ("a"."alarm_id" = "new"."alarm_id")), "assigned_to" = "new"."assignee_id", "start_at" = "new"."start_at", "end_at" = "new"."end_at", "reference" = "new"."reference", "time_spent" =
        CASE
            WHEN (("ticket"."parent_id" IS NULL) AND (NOT "public"."acl_check_access"('gui.tickets'::"text", 7))) THEN "ticket"."time_spent"
            ELSE "new"."time_spent"
        END
  WHERE ("ticket"."ticket_id" = "new"."ticket_id")
  RETURNING "ticket"."ticket_id",
    "ticket"."parent_id",
    "ticket"."title",
    "ticket"."description",
    "ticket"."priority",
    "ticket"."reason",
    "ticket"."state",
    "ticket"."contact",
    "ticket"."tags",
    "ticket"."created_by" AS "creator_id",
    "ticket"."created_at",
    "ticket"."assigned_to" AS "assignee_id",
    "ticket"."assigned_at",
    ( SELECT "eliona_user"."archived"
           FROM "public"."eliona_user"
          WHERE ("eliona_user"."user_id" = "ticket"."assigned_to")) AS "assignee_archived",
    "ticket"."closed_at",
    "ticket"."proj_id",
    "ticket"."asset_id",
    "ticket"."alarm_id",
    "ticket"."alarm",
    "api"."acl_access"("ticket"."asset_id") AS "acl_access",
    "ticket"."start_at",
    "ticket"."end_at",
    "ticket"."time_spent",
    "ticket"."reference",
    ( SELECT "sum"("c"."time_spent") AS "sum"
           FROM "public"."ticket" "c"
          WHERE ("c"."parent_id" = "ticket"."ticket_id")) AS "time_spent_total";


